-- ======================================================================
-- V2 — Identity, multi-tenancy, audit, and integration credential storage
-- ======================================================================
-- All organization-owned tables carry organization_id for tenant isolation.
-- All timestamps are TIMESTAMPTZ and written in UTC by the application.
-- All primary keys are UUIDs generated by the application layer.
-- ======================================================================

-- ----------------------------------------------------------------------
-- users — global principals. A user may belong to many organizations.
-- ----------------------------------------------------------------------
CREATE TABLE users (
    id              UUID         PRIMARY KEY,
    email           VARCHAR(320) NOT NULL,
    email_normalized VARCHAR(320) NOT NULL,
    password_hash   VARCHAR(255) NOT NULL,
    display_name    VARCHAR(120) NOT NULL,
    status          VARCHAR(32)  NOT NULL,
    last_login_at   TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_users_email_normalized UNIQUE (email_normalized),
    CONSTRAINT ck_users_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'DEACTIVATED'))
);

COMMENT ON COLUMN users.email_normalized IS
    'Lowercased email used for uniqueness and lookup; email preserves original casing.';

-- ----------------------------------------------------------------------
-- organizations — the tenant boundary.
-- ----------------------------------------------------------------------
CREATE TABLE organizations (
    id           UUID         PRIMARY KEY,
    name         VARCHAR(120) NOT NULL,
    slug         VARCHAR(64)  NOT NULL,
    demo_mode    BOOLEAN      NOT NULL DEFAULT TRUE,
    created_by   UUID         NOT NULL,
    created_at   TIMESTAMPTZ  NOT NULL,
    updated_at   TIMESTAMPTZ  NOT NULL,
    version      BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_organizations_slug UNIQUE (slug),
    CONSTRAINT fk_organizations_created_by FOREIGN KEY (created_by) REFERENCES users (id)
);

COMMENT ON COLUMN organizations.demo_mode IS
    'When true, HIGH_RISK actions are disabled for this organization (see Phase 6 policy engine).';

-- ----------------------------------------------------------------------
-- memberships — links a user to an organization with exactly one role.
-- ----------------------------------------------------------------------
CREATE TABLE memberships (
    id              UUID        PRIMARY KEY,
    organization_id UUID        NOT NULL,
    user_id         UUID        NOT NULL,
    role            VARCHAR(32) NOT NULL,
    status          VARCHAR(32) NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,
    version         BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT uq_memberships_org_user UNIQUE (organization_id, user_id),
    CONSTRAINT fk_memberships_org FOREIGN KEY (organization_id)
        REFERENCES organizations (id) ON DELETE CASCADE,
    CONSTRAINT fk_memberships_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT ck_memberships_role CHECK (
        role IN ('OWNER', 'ADMIN', 'RESPONDER', 'VIEWER', 'AUDITOR')),
    CONSTRAINT ck_memberships_status CHECK (status IN ('ACTIVE', 'SUSPENDED'))
);

CREATE INDEX ix_memberships_user ON memberships (user_id);
CREATE INDEX ix_memberships_org_role ON memberships (organization_id, role);

-- ----------------------------------------------------------------------
-- refresh_sessions — opaque rotating refresh tokens. Only the SHA-256
-- hash of the token is stored; the raw token is returned once, in an
-- httpOnly cookie, and never persisted or logged.
-- ----------------------------------------------------------------------
CREATE TABLE refresh_sessions (
    id                UUID         PRIMARY KEY,
    user_id           UUID         NOT NULL,
    token_hash        CHAR(64)     NOT NULL,
    -- Chain of rotated tokens. Reuse of a rotated token indicates theft.
    previous_id       UUID,
    issued_at         TIMESTAMPTZ  NOT NULL,
    expires_at        TIMESTAMPTZ  NOT NULL,
    revoked_at        TIMESTAMPTZ,
    revoked_reason    VARCHAR(64),
    user_agent        VARCHAR(255),
    ip_address        VARCHAR(64),
    CONSTRAINT uq_refresh_sessions_token_hash UNIQUE (token_hash),
    CONSTRAINT fk_refresh_sessions_user FOREIGN KEY (user_id)
        REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_refresh_sessions_user_active ON refresh_sessions (user_id, expires_at)
    WHERE revoked_at IS NULL;

COMMENT ON COLUMN refresh_sessions.token_hash IS
    'SHA-256 hex of the opaque refresh token. The raw token is never stored.';

-- ----------------------------------------------------------------------
-- audit_events — append-only. Updates and deletes are blocked by trigger
-- so the trail remains immutable even against application-layer bugs.
-- ----------------------------------------------------------------------
CREATE TABLE audit_events (
    id              UUID         PRIMARY KEY,
    organization_id UUID,
    actor_user_id   UUID,
    actor_type      VARCHAR(32)  NOT NULL,
    actor_label     VARCHAR(255),
    action          VARCHAR(96)  NOT NULL,
    resource_type   VARCHAR(64)  NOT NULL,
    resource_id     VARCHAR(128),
    outcome         VARCHAR(32)  NOT NULL,
    reason          VARCHAR(512),
    correlation_id  VARCHAR(64),
    ip_address      VARCHAR(64),
    metadata        JSONB        NOT NULL DEFAULT '{}'::jsonb,
    occurred_at     TIMESTAMPTZ  NOT NULL,
    CONSTRAINT ck_audit_events_actor_type CHECK (
        actor_type IN ('USER', 'SYSTEM', 'WORKFLOW', 'INTEGRATION', 'ANONYMOUS')),
    CONSTRAINT ck_audit_events_outcome CHECK (
        outcome IN ('SUCCESS', 'FAILURE', 'DENIED'))
);

-- No FK on organization_id/actor_user_id: audit records must survive the
-- deletion of the entities they describe.
CREATE INDEX ix_audit_events_org_time ON audit_events (organization_id, occurred_at DESC);
CREATE INDEX ix_audit_events_actor_time ON audit_events (actor_user_id, occurred_at DESC);
CREATE INDEX ix_audit_events_action ON audit_events (action, occurred_at DESC);
CREATE INDEX ix_audit_events_correlation ON audit_events (correlation_id);

CREATE OR REPLACE FUNCTION audit_events_reject_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'audit_events is append-only; % is not permitted', TG_OP;
END;
$$;

CREATE TRIGGER trg_audit_events_no_update
    BEFORE UPDATE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION audit_events_reject_mutation();

CREATE TRIGGER trg_audit_events_no_delete
    BEFORE DELETE ON audit_events
    FOR EACH ROW EXECUTE FUNCTION audit_events_reject_mutation();

-- ----------------------------------------------------------------------
-- integrations — one configured external connection per organization.
-- ----------------------------------------------------------------------
CREATE TABLE integrations (
    id                  UUID         PRIMARY KEY,
    organization_id     UUID         NOT NULL,
    kind                VARCHAR(32)  NOT NULL,
    name                VARCHAR(120) NOT NULL,
    environment         VARCHAR(32)  NOT NULL,
    status              VARCHAR(32)  NOT NULL,
    config              JSONB        NOT NULL DEFAULT '{}'::jsonb,
    last_success_at     TIMESTAMPTZ,
    last_error_at       TIMESTAMPTZ,
    last_error_message  VARCHAR(512),
    created_by          UUID         NOT NULL,
    created_at          TIMESTAMPTZ  NOT NULL,
    updated_at          TIMESTAMPTZ  NOT NULL,
    version             BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_integrations_org_name UNIQUE (organization_id, name),
    CONSTRAINT fk_integrations_org FOREIGN KEY (organization_id)
        REFERENCES organizations (id) ON DELETE CASCADE,
    CONSTRAINT ck_integrations_kind CHECK (
        kind IN ('GITHUB', 'SENTRY', 'SLACK', 'EMAIL', 'JIRA', 'CUSTOM_WEBHOOK', 'HTTP_HEALTHCHECK')),
    CONSTRAINT ck_integrations_environment CHECK (
        environment IN ('DEVELOPMENT', 'STAGING', 'PRODUCTION')),
    CONSTRAINT ck_integrations_status CHECK (
        status IN ('PENDING', 'CONNECTED', 'DEGRADED', 'DISCONNECTED', 'ERROR'))
);

CREATE INDEX ix_integrations_org_kind ON integrations (organization_id, kind);

COMMENT ON COLUMN integrations.config IS
    'Non-secret configuration only. Secrets live in integration_credential_references.';

-- ----------------------------------------------------------------------
-- integration_credential_references — AES-GCM encrypted secret material.
-- The plaintext is never returned by any API after creation.
-- ----------------------------------------------------------------------
CREATE TABLE integration_credential_references (
    id                UUID         PRIMARY KEY,
    organization_id   UUID         NOT NULL,
    integration_id    UUID         NOT NULL,
    credential_key    VARCHAR(64)  NOT NULL,
    ciphertext        TEXT         NOT NULL,
    nonce             VARCHAR(64)  NOT NULL,
    key_id            VARCHAR(64)  NOT NULL,
    -- Non-reversible fingerprint so operators can confirm which secret is
    -- installed without ever revealing it.
    fingerprint       CHAR(12)     NOT NULL,
    revoked_at        TIMESTAMPTZ,
    created_at        TIMESTAMPTZ  NOT NULL,
    updated_at        TIMESTAMPTZ  NOT NULL,
    version           BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_integration_credential_key UNIQUE (integration_id, credential_key),
    CONSTRAINT fk_credential_org FOREIGN KEY (organization_id)
        REFERENCES organizations (id) ON DELETE CASCADE,
    CONSTRAINT fk_credential_integration FOREIGN KEY (integration_id)
        REFERENCES integrations (id) ON DELETE CASCADE
);

CREATE INDEX ix_credential_org ON integration_credential_references (organization_id);

COMMENT ON COLUMN integration_credential_references.key_id IS
    'Identifier of the master key used, enabling key rotation without re-reading plaintext.';
